local function MeasureRow(container)
    if not container.font then return end
    local height = container.font:GetStringHeight() + 10
    if container.rowKind == "divider" then
        height = 12
    elseif container.progressBarOnly then
        height = 30
    elseif container.detailFonts then
        for index, font in ipairs(container.detailFonts) do
            if index <= #container.subTexts then
                if font.layoutOffset ~= height then
                    font:ClearAllPoints()
                    font:SetPoint("TOPLEFT", container, "TOPLEFT", INDENT, -height)
                    font.layoutOffset = height
                end
                height = height + font:GetStringHeight() + DETAIL_GAP
            end
        end
        height = height + 5
    else
        height = height + (container.extraContentHeight or 0)
    end
    if container.IconButton or container.RaidIconButton then height = math.max(height, 30) end
    if container:GetHeight() ~= height then
        if CurrentStep:CanSafelyHide(container) then
            container:SetHeight(height)
        else
            CurrentStep.layoutDirty = true
        end
    end
end--[[APR_DIAG]]; MeasureRow = APRTrace("APR-Core/ui/route/CurrentStepRows.lua:325:MeasureRow#24", MeasureRow)--[[/APR_DIAG]]

local function ResizeRow(container)
    if not CurrentStep:CanSafelyHide(container) then return end
    if container:GetWidth() ~= Layout.width then container:SetWidth(Layout.width) end
    if container.font then container.font:SetWidth(Layout.width - PADDING * 2) end
    for _, font in ipairs(container.detailFonts or {}) do font:SetWidth(Layout.width - INDENT - PADDING) end
end--[[APR_DIAG]]; ResizeRow = APRTrace("APR-Core/ui/route/CurrentStepRows.lua:357:ResizeRow#25", ResizeRow)--[[/APR_DIAG]]

function CurrentStep:SetContentWidth(width)
    if InCombatLockdown() or Layout.width == width then return end
    Layout.width = width
    CurrentStepScreenPanel:SetWidth(width)
    if self.progressBar then self.progressBar:SetWidth(self:GetProgressBarWidth(width)) end
    if APR.RouteSelection then APR.RouteSelection:Layout() end
    if APR.currentStepImagePreview then
        APR.currentStepImagePreview:ConfigureCurrentStepPreview(CurrentStepFrame_StepHolder, width)
    end
    for _, list in ipairs({self.questsList, self.questsExtraTextList}) do
        for _, row in pairs(list) do
            ResizeRow(row)
            if row.rowKind == "preview" and APR.currentStepImagePreview then
                APR.currentStepImagePreview:RefreshPreviewLayout(row)
            end
        end
    end
    self:ReOrderQuestSteps()
end--[[APR_DIAG]]; CurrentStep.SetContentWidth = APRTrace("APR-Core/ui/route/CurrentStepRows.lua:364:CurrentStep:SetContentWidth#26", CurrentStep.SetContentWidth)--[[/APR_DIAG]]

