function CurrentStep:ReOrderQuestSteps()
    self.layoutDirty = true
    if self.questUpdateDepth then self.questLayoutPending = true; return end
    if self.contentUpdateActive or not APR.settings.profile.currentStepShow then return end
    self.questLayoutPending = nil
    self.layoutDirty = false
    if self.emptyRoutePromptActive and self.emptyRoutePrompt and self.emptyRoutePrompt:IsShown() then
        self.FrameHeight = self.emptyRoutePrompt:GetHeight() + 16
        self:UpdatePanelHeight()
        APR:RefreshSnappedFrames()
        return
    end
    local firstKey = APR.navigation and APR.navigation.ErrorDestinationLineKey or "00_ERROR_DESTINATION"
    local groups = { OrderedRows(self.questsExtraTextList, firstKey), OrderedRows(self.questsList) }
    local autoCount = 0
    for _, rows in ipairs(groups) do
        for _, entry in ipairs(rows) do
            local row = entry.container
            APR:SetPanelColor(row, {0, 0, 0, 0})
            if row._isManagedExtraLine and row._manualLeadingDash == nil then autoCount = autoCount + 1 end
        end
    end
    local offset = TOP_OFFSET
    for _, rows in ipairs(groups) do
        for _, entry in ipairs(rows) do
            local row = entry.container
            if row._isManagedExtraLine then
                local dash = row._manualLeadingDash
                if dash == nil then dash = autoCount > 1 end
                row.showLeadingDash = dash
                SetText(row.font, (dash and "- " or "") .. row._rawExtraLineText)
            end
            if row.rowKind ~= "divider" then MeasureRow(row) end
            -- Secure descendants also protect their parent's anchors in combat.
            if row.layoutOffset ~= offset then
                if self:CanSafelyHide(row) then
                    row:ClearAllPoints()
                    row:SetPoint("TOPLEFT", CurrentStepScreenPanel, "TOPLEFT", 0, -offset)
                    row.layoutOffset = offset
                else
                    self.layoutDirty = true
                end
            end
            offset = offset + row:GetHeight()
        end
    end
    self.FrameHeight = offset
    self:UpdatePanelHeight()
    APR:RefreshSnappedFrames()
    if APR.Gamepad then APR.Gamepad:Refresh(CurrentStepScreenPanel) end
end--[[APR_DIAG]]; CurrentStep.ReOrderQuestSteps = APRTrace("APR-Core/ui/route/CurrentStepRows.lua:631:CurrentStep:ReOrderQuestSteps#42", CurrentStep.ReOrderQuestSteps)--[[/APR_DIAG]]

function CurrentStep:RefreshTextLayout() self:ReOrderQuestSteps() end--[[APR_DIAG]]; CurrentStep.RefreshTextLayout = APRTrace("APR-Core/ui/route/CurrentStepRows.lua:683:CurrentStep:RefreshTextLayout#43", CurrentStep.RefreshTextLayout)--[[/APR_DIAG]]
